insert into public.families (slug, name, description, theme_color, is_public_visible, status)
insert into public.dishes (id, family_id, title, slug, description, rating, price_amount, price_currency, prep_time, cook_time, total_time, calories, servings, difficulty, tags, categories, taste_sweet, taste_salty, taste_sour, taste_bitter, taste_spicy, taste_umami, notes, source_url, visibility, status, created_at, updated_at) values
('dish-034', (select id from public.families where slug='bulkina-family'), 'Трикутнички', 'trykutnychky', 'Хрусткі трикутнички з тонкого лаваша з начинкою зі смаженого рибного філе, тертого сиру та соусу тартар, обсмажені в яйці до золотистої скоринки. Швидка та ситна закуска або гаряче.', 5, 220, 'UAH', 15, 20, 35, 440, 6, 'easy', ARRAY['лаваш','риба','рибне філе','сир','тартар','смажене','закуска','трикутнички']::text[], ARRAY['snack','quick','everyday']::text[], 0, 3, 2, 0, 0, 4, 'Орієнтовне КБЖВ на 1 трикутник (~130 г): ~440 ккал, білки ~22 г, жири ~28 г, вуглеводи ~25 г. На 100 г — приблизно 340 ккал, білки ~17 г, жири ~21 г, вуглеводи ~19 г. Значення приблизні та залежать від виду риби, кількості сиру й тартару. Сир і тартар додавайте на око — стільки, щоб начинка вийшла соковитою, а не сухою.', '', 'family', 'published', '2026-07-09T12:00:00.000Z', '2026-07-09T12:00:00.000Z'),
('dish-033', (select id from public.families where slug='bulkina-family'), 'ПП курячі оладки / котлети на сковороді', 'pp-kuriachi-oladky-kotlety-na-skovorodi', 'Соковиті білкові курячі оладки з філе, яєць, сиру, йогурту або сметани та мінімальної кількості вівсянки. Щось між сирними курячими драниками, рубленими котлетами і легкою KFC-style стравою без великої кількості олії.', 5, 300, 'UAH', 15, 18, 35, 390, 4, 'easy', ARRAY['пп','курка','куряче філе','білкове','на сковороді','котлети','оладки','healthy']::text[], ARRAY['lunch','dinner','healthy','everyday']::text[], 0, 3, 0, 0, 1, 4, 'Орієнтовне КБЖВ всього рецепта: білки ~155–170 г, жири ~45–55 г, вуглеводи ~15–25 г, калорії ~1400–1700 ккал. На 4 порції виходить приблизно 350–425 ккал на порцію. Якщо маса занадто рідка — додайте ще 1 ложку вівсянки. Якщо занадто щільна — додайте ще 1 ложку йогурту або сметани.', '', 'family', 'published', '2026-05-22T08:03:40.924Z', '2026-05-22T08:03:40.924Z'),
('dish-032', (select id from public.families where slug='bulkina-family'), 'Курка в кисло-солодкому соусі', 'kurka-kyslo-solodkyi-sous', 'Швидка і соковита курка в кисло-солодкому соусі — чудовий вибір для обіду, перекусу або вечері. Подавайте з рисом або як самостійну страву.', 5, 220, 'UAH', 10, 10, 20, 720, 2, 'easy', ARRAY['курка','кисло-солодке','швидко','марафон']::text[], ARRAY['dinner','lunch','snack']::text[], 3, 3, 2, 0, 1, 4, 'Вага порції ≈ 550 г. Для подачі — зелена цибуля і кунжут. Ідеально для марафону схуднення при контрольованих порціях.', 'https://www.instagram.com/reels/DT0vSfwjDEc/', 'family', 'published', '2026-02-28T11:40:00.000Z', '2026-02-28T11:40:00.000Z'),
('dish-031', (select id from public.families where slug='bulkina-family'), 'Шоколадний Брауні 🍫', 'shokoladnyi-brauni', 'Щільний шоколадний брауні з вологою серединкою — ідеальний десерт для поділу або з шаріком ванільного морозива.', 5, 0, 'UAH', 15, 25, 40, 420, 9, 'easy', ARRAY['брауні','шоколад','десерт','випічка']::text[], ARRAY['dessert','baking']::text[], 5, 0, 0, 2, 0, 0, 'Не пересушуйте — середина повинна лишатися трохи вологою. Охолоджуйте повністю перед нарізанням.', 'https://www.instagram.com/reels/DT7r6aiDBei/', 'family', 'published', '2026-02-28T11:20:00.000Z', '2026-02-28T11:20:00.000Z'),
('dish-030', (select id from public.families where slug='bulkina-family'), 'Торт «Черепашка»', 'tort-cherepashka', 'Домашній торт «Черепашка» з шоколадного бісквітного тіста та сметанно-шоколадного крему. Шматочки бісквіта занурюються в крем і викладаються гіркою.', 5, 220, 'UAH', 20, 15, 155, 360, 8, 'easy', ARRAY['торт','черепашка','шоколадний','сметанний крем','десерт']::text[], ARRAY['dessert','baking','festive']::text[], 5, 0, 1, 1, 0, 0, 'Крем обов''язково має охолонути перед додаванням сметани, щоб вона не згорнулась.', '', 'family', 'published', '2026-02-25T00:00:00.000Z', '2026-02-28T11:45:52.359Z'),
('dish-029', (select id from public.families where slug='bulkina-family'), 'Трендовий пиріг з горішками та згущеним молоком', 'trendovyi-pyrih-z-horishkamy-ta-zhushchenym-molokom', 'Трендовий пиріг для поціновувачів горішків зі згущеним молоком — пісочне тісто з ніжною начинкою із вареного згущеного молока, сметани та горішків. Випікається при 170°C всього 35 хвилин.', 5, 250, 'UAH', 75, 35, 110, 380, 8, 'medium', ARRAY['пиріг','горішки','згущене молоко','випічка','тренд','десерт']::text[], ARRAY['dessert','baking']::text[], 5, 1, 1, 0, 0, 1, 'Масло обов''язково має бути м''яким, не розтопленим. Тісто потрібно охолодити мінімум годину — так воно краще тримає форму. Після випікання дайте пирогу добре охолонути — начинка стабілізується і буде тримати форму при нарізанні.', 'https://www.instagram.com/reels/DUYeIfQjKnF/', 'family', 'published', '2026-02-18T00:00:00.000Z', '2026-02-18T00:00:00.000Z'),
('dish-028', (select id from public.families where slug='bulkina-family'), 'Фрикадельки з макаронами в одній сковороді', 'frykadelky-z-makaronamy-v-odnii-skovorodi', 'Ситна вечеря в одній сковороді — маленькі фрикадельки з фаршу, обсмажені до рум''яності, з макаронами у томатному соусі. Швидко, просто і дуже смачно.', 5, 280, 'UAH', 15, 25, 40, 350, 4, 'easy', ARRAY['фрикадельки','макарони','фарш','в одній сковороді','вечеря','томатний соус']::text[], ARRAY['dinner','quick','everyday']::text[], 1, 3, 2, 0, 1, 5, 'Фарш краще готувати як на котлети — добре відбити для кращої консистенції. Фрикадельки мають бути маленькими, щоб швидше просмажились. Макарони обирайте дрібні — вони краще вбирають соус.', 'https://www.instagram.com/reel/DFDlh5kNRGo/', 'family', 'published', '2026-02-13T00:00:00.000Z', '2026-02-13T00:00:00.000Z'),
('dish-027', (select id from public.families where slug='bulkina-family'), 'Сочники з сиром', 'sochnyky-z-syrom', 'Класичні сочники — ніжне пісочне тісто на сметані з кисломолочною сирною начинкою. М''які, розсипчасті та дуже смачні. Вихід — 12-13 штук.', 5, 220, 'UAH', 80, 30, 110, 290, 13, 'easy', ARRAY['сочники','сир','випічка','печиво','сметана']::text[], ARRAY['baking','dessert','everyday']::text[], 4, 1, 1, 0, 0, 1, 'Тісто м''яке — обов''язково охолодити в холодильнику перед формуванням. Не кладіть занадто багато начинки, щоб сочники не розкрились під час випікання.', 'https://www.instagram.com/reel/DAOOwJzNs36/', 'family', 'published', '2026-02-09T00:00:00.000Z', '2026-02-09T00:00:00.000Z'),
('dish-026', (select id from public.families where slug='bulkina-family'), 'Круасани з шинкою і сиром', 'kruasany-z-shynkoyu-i-syrom', 'Швидкі круасани з готового листково-дріжджового тіста з начинкою з шинки та сиру, посипані кунжутом. Чудова закуска або перекус.', 4, 200, 'UAH', 15, 25, 40, 310, 8, 'easy', ARRAY['круасани','шинка','сир','листкове тісто','кунжут','перекус']::text[], ARRAY['snack','quick','everyday']::text[], 0, 3, 0, 0, 0, 3, 'Використовуйте готове листково-дріжджове тісто для швидкості. Можна експериментувати з начинками — додати гірчицю, зелень або інші сири.', 'https://www.instagram.com/reel/DP151uWDdhN/', 'family', 'published', '2026-02-08T23:55:00.000Z', '2026-02-08T23:55:00.000Z'),
('dish-025', (select id from public.families where slug='bulkina-family'), 'Сінабони з корицею', 'sinabony-z-koryceyu', 'Класичні сінабони — м''які дріжджові булочки з начинкою з кориці та цукру, покриті ніжним кремом з крем-сиру. Вихід — 8-10 штук.', 5, 350, 'UAH', 40, 35, 195, 380, 10, 'medium', ARRAY['сінабони','кориця','булочки','дріжджові','крем-сир']::text[], ARRAY['baking','dessert']::text[], 5, 1, 0, 0, 1, 0, 'Тісто має добре відлипати від рук — якщо після довгого вимішування все ще липне, додайте трішечки борошна. Крем наносити саме на гарячі булочки, щоб він трохи розтанув та просочив тісто.', 'https://www.instagram.com/reel/DPoHfGFiN3v/', 'family', 'published', '2026-02-08T23:50:00.000Z', '2026-02-08T23:50:00.000Z'),
('dish-024', (select id from public.families where slug='bulkina-family'), 'Високобілковий хліб', 'vysokobilkovyj-khlib', 'Корисний високобілковий хліб без борошна — на основі вівсяних пластівців та кисломолочного сиру. Ідеальна основа для бутербродів з авокадо або рибкою. Вихід — 2 булки.', 4, 200, 'UAH', 10, 50, 60, 180, 2, 'easy', ARRAY['хліб','високобілковий','корисний','без борошна','вівсянка','ПП']::text[], ARRAY['healthy','breakfast','baking']::text[], 0, 2, 1, 0, 0, 2, 'Можна використовувати безглютенову вівсянку та безлактозний сир. Чудово поєднується з авокадо, рибою або іншими корисними жирами для повноцінного прийому їжі.', 'https://www.instagram.com/reel/DLXw9EuNAym/', 'family', 'published', '2026-02-08T23:45:00.000Z', '2026-02-08T23:45:00.000Z'),
('dish-023', (select id from public.families where slug='bulkina-family'), 'Ягідні кекси', 'yahidni-keksy', 'Швидкі ягідні кекси за кілька хвилин — м''яке тісто з чорницями або будь-якими сезонними ягодами. Ідеальна літня випічка на 10-12 штук.', 5, 180, 'UAH', 10, 20, 30, 250, 12, 'easy', ARRAY['кекси','ягоди','чорниці','випічка','швидко']::text[], ARRAY['baking','dessert','quick']::text[], 4, 0, 1, 0, 0, 0, 'Можна використовувати будь-які сезонні ягоди. Якщо ягоди кислі (наприклад, смородина), варто додати більше цукру. Кількість кексів залежить від розміру форми — 10-12 шт.', 'https://www.instagram.com/reel/DLmszEftALn/', 'family', 'published', '2026-02-08T23:30:00.000Z', '2026-02-08T23:30:00.000Z'),
('dish-022', (select id from public.families where slug='bulkina-family'), 'Чізкейк «Snickers»', 'chizkejk-snickers', 'Розкішний чізкейк у стилі батончика Snickers — пісочна основа з какао, ніжна сирна начинка, домашня карамель з підсмаженим арахісом зверху. Ідеальний святковий десерт.', 5, 650, 'UAH', 30, 55, 505, 420, 8, 'hard', ARRAY['чізкейк','снікерс','карамель','арахіс','какао','крем сир']::text[], ARRAY['dessert','baking','festive']::text[], 5, 2, 1, 1, 0, 1, 'Чізкейк обов''язково потрібно повністю охолодити перед нанесенням карамелі. Карамель має бути теплою, але не гарячою, інакше чізкейк може потріскатися. Найкраще залишити в холодильнику на ніч.', 'https://www.instagram.com/reel/DPI8GmBDIvq/', 'family', 'published', '2026-02-08T23:00:00.000Z', '2026-02-08T23:00:00.000Z'),
('dish-021', (select id from public.families where slug='bulkina-family'), 'Cinnamon Bows', 'cinnamon-bows', 'Різдвяна випічка у формі бантиків з корицею — cute cinnamon rolls у формі бантиків. Рецепт потребує допрацювання.', 0, 0, 'UAH', 0, 0, 0, 0, 0, 'medium', ARRAY['кориця','різдво','булочки','бантики','TODO']::text[], ARRAY['baking','dessert','festive']::text[], 0, 0, 0, 0, 0, 0, '⚠️ РЕЦЕПТ НЕ ЗАПОВНЕНИЙ — потрібно знайти або написати рецепт. Джерело — англомовний пост без детальних вимірювань.', 'https://www.instagram.com/reel/DRP3r2QiAfZ/', 'family', 'published', '2026-02-08T22:30:00.000Z', '2026-02-08T22:30:00.000Z'),
('dish-020', (select id from public.families where slug='bulkina-family'), 'Трдельник', 'trdelnyk', 'Чеський трдельник — дріжджове тісто, намотане спіраллю на валик і випечене до золотистої хрусткої скоринки. Обвалюється у суміші цукру, кориці та горіхів або кокосовій стружці.', 5, 250, 'UAH', 90, 20, 110, 380, 6, 'medium', ARRAY['трдельник','чеська кухня','дріжджове тісто','випічка','вулична їжа']::text[], ARRAY['baking','dessert','festive']::text[], 5, 0, 0, 0, 1, 1, 'У духовці можна використати конуси з фольги або металеві трубки. Для шоколадного варіанту — полити розтопленим шоколадом та посипати кокосовою стружкою. Подавати гарячим, можна наповнити морозивом або збитими вершками.', 'https://www.instagram.com/reel/DQyWXRlCPzX/', 'family', 'published', '2026-02-08T22:00:00.000Z', '2026-02-08T22:00:00.000Z'),
('dish-019', (select id from public.families where slug='bulkina-family'), 'Піцабони', 'pitsabony', 'Швидка закуска з листкового тіста з начинкою з шинки, сиру та томатної пасти. Рулетики нарізаються кружальцями та запікаються — ідеальний перекус.', 5, 180, 'UAH', 10, 20, 30, 290, 6, 'easy', ARRAY['піца','листкове тісто','шинка','сир','закуска']::text[], ARRAY['snack','quick','everyday']::text[], 0, 3, 1, 0, 0, 4, 'Начинку можна змінювати — додавати гриби, оливки, перець. Тісто краще не розморожувати повністю, щоб легше було працювати.', 'https://www.instagram.com/reel/DPBAlaEjED3/', 'family', 'published', '2026-02-08T21:30:00.000Z', '2026-02-08T21:30:00.000Z'),
('dish-018', (select id from public.families where slug='bulkina-family'), 'Узбекський плов', 'uzbekskyi-plov', 'Класичний узбекський плов зі свининою, довгим рисом, морквою та часником. Ароматний, ситний та дуже смачний — готується в одній каструлі.', 5, 300, 'UAH', 40, 80, 120, 350, 6, 'medium', ARRAY['плов','рис','свинина','узбекський','м''ясо']::text[], ARRAY['dinner','lunch','everyday']::text[], 1, 3, 0, 0, 2, 5, 'Рис краще брати довгий пропарений — він не злипається. Моркву нарізати саме соломкою, не натирати. Часник закладається цілою головкою і подається окремо.', 'https://www.instagram.com/reel/C_ntXtEt25D/', 'family', 'published', '2026-02-08T21:00:00.000Z', '2026-02-08T21:00:00.000Z'),
('dish-017', (select id from public.families where slug='bulkina-family'), 'Різдвяна зірка', 'rizdviana-zirka', 'Святкова дріжджова випічка у формі зірки з начинкою — красива, м''яка та ароматна. Чудовий десерт для святкового столу.', 5, 250, 'UAH', 80, 25, 105, 340, 8, 'medium', ARRAY['зірка','дріжджове тісто','різдво','свято','випічка']::text[], ARRAY['baking','dessert','festive']::text[], 4, 0, 0, 0, 0, 1, 'Начинка може бути будь-якою — маковою, горіховою, з корицею та цукром, або навіть нутеллою. Зірку краще формувати на пергаменті, щоб легко перенести на деко.', 'https://www.instagram.com/reel/DSc02ZADGmG/', 'family', 'published', '2026-02-08T20:30:00.000Z', '2026-02-08T20:30:00.000Z'),
('dish-016', (select id from public.families where slug='bulkina-family'), 'Гуляш зі свинини з овочами', 'huliash-zi-svynyny-z-ovochamy', 'Ситний гуляш зі свинини з картоплею, морквою, грибами та томатною пастою — повноцінна вечеря в одній сковорідці.', 5, 350, 'UAH', 15, 40, 55, 320, 6, 'easy', ARRAY['гуляш','свинина','картопля','гриби','одна сковорідка']::text[], ARRAY['dinner','everyday','lunch']::text[], 1, 3, 1, 0, 1, 5, 'Борошно додається для загущення соусу. Спеції за смаком — паприка, лавровий лист, сушений часник чудово пасують.', 'https://www.instagram.com/reel/DJFCFSqtcxc/', 'family', 'published', '2026-02-08T20:00:00.000Z', '2026-02-08T20:00:00.000Z'),
('dish-015', (select id from public.families where slug='bulkina-family'), 'Кекс Зебра', 'keks-zebra', 'Класичний двоколірний кекс Зебра — м''який, вологий, з красивим смугастим візерунком. Простий у приготуванні фаворит серед кексів.', 5, 200, 'UAH', 15, 50, 65, 360, 8, 'easy', ARRAY['кекс','зебра','какао','випічка','класика']::text[], ARRAY['baking','dessert']::text[], 4, 0, 1, 1, 0, 1, 'Дати кексу повністю охолонути перед нарізанням. Особливо смачний з молоком чи чаєм.', 'https://www.instagram.com/reel/DAlogDetFP4/', 'family', 'published', '2026-02-08T19:30:00.000Z', '2026-02-08T19:30:00.000Z'),
('dish-014', (select id from public.families where slug='bulkina-family'), 'Вареники з вишнею', 'varenyky-z-vyshneiu', 'Домашні вареники з вишнею — еластичне тісто на воді та олії з соковитою ягідною начинкою. Подавати з маслом, цукром або вишневим соусом.', 5, 180, 'UAH', 40, 10, 50, 220, 6, 'medium', ARRAY['вареники','вишня','тісто','ягоди','домашні']::text[], ARRAY['dinner','everyday','dessert']::text[], 4, 1, 3, 0, 0, 0, 'Тісто дуже еластичне та не потребує додаткового борошна. Подавати з вершковим маслом і цукром або з вишневим соусом (1 склянка вишні, 1 ст.л. крохмалю, 1–2 ст.л. цукру, ~50 г води — прогріти до загущення). Вихід — ~36 штук.', 'https://www.instagram.com/reel/C8Zdsz1Naro/', 'family', 'published', '2026-02-08T19:00:00.000Z', '2026-02-08T19:00:00.000Z'),
('dish-013', (select id from public.families where slug='bulkina-family'), 'Яблучний пиріг з дитинства', 'yabluchnyi-pyrih-z-dytynstva', 'Ніжний яблучний пиріг з м''яким тістом і шматочками яблук — простий, як з дитинства. Мінімум інгредієнтів, максимум смаку.', 5, 120, 'UAH', 15, 30, 45, 310, 6, 'easy', ARRAY['пиріг','яблука','випічка','дитинство','солодке']::text[], ARRAY['baking','dessert']::text[], 4, 0, 2, 0, 0, 0, 'Яблука краще брати кисло-солодкі. Пиріг особливо смачний теплим, із кулькою ванільного морозива або ложкою сметани.', 'https://www.instagram.com/reel/DNkUlEhInpM/', 'family', 'published', '2026-02-08T18:30:00.000Z', '2026-02-08T18:30:00.000Z'),
('dish-012', (select id from public.families where slug='bulkina-family'), 'Картопля з фаршем у духовці', 'kartoplia-z-farshem-u-dukhovtsi', 'Картопля з м''ясним фаршем, запечена під сметанно-томатною заливкою. Проста, ситна і дуже смачна страва на кожен день.', 5, 200, 'UAH', 15, 45, 60, 280, 4, 'easy', ARRAY['картопля','фарш','у духовці','сметана','томатна паста']::text[], ARRAY['dinner','everyday','lunch']::text[], 1, 3, 1, 0, 1, 4, 'Картоплю нарізайте не надто товсто, щоб вона встигла пропектися разом із фаршем. За бажанням можна посипати сиром за 5 хвилин до готовності.', 'https://www.instagram.com/reel/DManxfhoBvQ/', 'family', 'published', '2026-02-08T18:00:00.000Z', '2026-02-08T18:00:00.000Z'),
('dish-011', (select id from public.families where slug='bulkina-family'), 'Фінський млинець-рулет у духовці', 'finskyi-mlynets-rulet-u-dukhovtsi', 'Великий пухкий млинець, запечений у духовці і скручений у рулет з кокосовою стружкою. Простий і ефектний сніданок.', 5, 150, 'UAH', 10, 20, 30, 280, 4, 'easy', ARRAY['млинець','фінський','духовка','рулет','кокос']::text[], ARRAY['breakfast','baking','quick']::text[], 3, 1, 0, 0, 0, 1, 'Скручувати потрібно поки млинець ще гарячий — так він не тріскається. Замість кокосу можна використати джем, нутеллу або ягоди.', 'https://www.instagram.com/reel/DM9ucOjo3GV/', 'family', 'published', '2026-02-08T17:30:00.000Z', '2026-02-08T17:30:00.000Z'),
('dish-010', (select id from public.families where slug='bulkina-family'), 'Булочки з маком', 'bulochky-z-makom', 'Пухкі дріжджові булочки з щедрою маковою начинкою. Тісто на опарі виходить м''яке та повітряне.', 5, 200, 'UAH', 60, 25, 85, 350, 10, 'medium', ARRAY['булочки','мак','дріжджове тісто','випічка','солодке']::text[], ARRAY['baking','dessert','snack']::text[], 4, 0, 0, 1, 0, 1, 'Готову макову начинку можна купити або зробити самостійно — мак проварити, перемолоти з цукром.', 'https://www.instagram.com/reel/CqVkNXjjZsT/', 'family', 'published', '2026-02-08T17:00:00.000Z', '2026-02-08T17:00:00.000Z'),
('dish-009', (select id from public.families where slug='bulkina-family'), 'Чебуреки', 'chebureki', 'Хрусткі чебуреки з соковитою м''ясною начинкою — заварне тісто на окропі з фаршем яловичини та свинини з кінзою. Класика вуличної їжі вдома.', 5, 250, 'UAH', 30, 30, 120, 300, 10, 'medium', ARRAY['чебуреки','фарш','смажене','тісто','м''ясо']::text[], ARRAY['dinner','snack','everyday']::text[], 0, 3, 0, 0, 2, 4, 'Головний секрет соковитих чебуреків — крижана вода в начинці. Тісто обов''язково має відпочити в холодильнику мінімум 1 годину.', 'https://www.instagram.com/reel/C-s_3fhtNmU/', 'family', 'published', '2026-02-08T16:30:00.000Z', '2026-02-08T16:30:00.000Z'),
('dish-008', (select id from public.families where slug='bulkina-family'), 'Бюджетні млинці без яєць та молока', 'biudzhetni-mlyntsi-bez-yaiets-ta-moloka', 'Найпростіший рецепт млинців — лише борошно, вода і сіль. За бажанням можна додати 1 яйце. Ідеально коли немає продуктів або під час блекауту.', 4, 30, 'UAH', 5, 25, 30, 150, 10, 'easy', ARRAY['млинці','бюджетно','без яєць','без молока','просто']::text[], ARRAY['breakfast','quick','everyday','vegetarian']::text[], 0, 1, 0, 0, 0, 0, 'Рецепт максимально бюджетний — підходить, коли в холодильнику майже нічого немає. Можна начинити будь-чим: фаршем, сиром, джемом.', 'https://www.instagram.com/reel/DL5CLrZxhNz/', 'family', 'published', '2026-02-08T16:00:00.000Z', '2026-02-08T16:00:00.000Z'),
('dish-007', (select id from public.families where slug='bulkina-family'), 'Шоколадна ковбаска', 'shokoladna-kovbaska', 'Класичний десерт з дитинства — шоколадна ковбаска з печива, горіхів, какао та вершкового масла. Без випікання!', 5, 250, 'UAH', 20, 0, 200, 420, 8, 'easy', ARRAY['десерт','без випікання','шоколад','дитинство','печиво']::text[], ARRAY['dessert','snack']::text[], 5, 0, 0, 2, 0, 1, 'Печиво бажано ламати руками, а не молоти в крихту — так ковбаска буде цікавішою за текстурою.', 'https://www.instagram.com/reel/CxgEotdNEj7/', 'family', 'published', '2026-02-08T15:30:00.000Z', '2026-02-08T15:30:00.000Z'),
('dish-006', (select id from public.families where slug='bulkina-family'), 'Запіканка з макаронами та фаршем', 'zapikanka-z-makaronamy-ta-farshem', 'Ситна запіканка з макаронами, фаршем, вершковим соусом та сиром. Простий рецепт для смачної родинної вечері.', 5, 280, 'UAH', 15, 30, 45, 350, 6, 'easy', ARRAY['запіканка','макарони','фарш','у духовці','вершки']::text[], ARRAY['dinner','everyday']::text[], 0, 3, 0, 0, 1, 4, 'Макарони краще недоварити, бо вони дійдуть у духовці. Сир бере будь-який, що добре плавиться.', 'https://www.instagram.com/reel/DPy7iPejJWo/', 'family', 'published', '2026-02-08T15:00:00.000Z', '2026-02-08T15:00:00.000Z'),
('dish-005', (select id from public.families where slug='bulkina-family'), 'Маковий кранч', 'makovyi-kranch', 'М''яке, повітряне дріжджове тісто з щедрою маковою начинкою, сплетене у красиву косичку. Ідеальна випічка до чаю чи кави.', 5, 300, 'UAH', 90, 35, 125, 380, 8, 'medium', ARRAY['випічка','мак','дріжджове тісто','кранч','солодке']::text[], ARRAY['baking','dessert','festive']::text[], 4, 0, 0, 1, 0, 1, 'Борошна краще трохи недосипати, ніж перебити — тісто має бути м''яким і злегка розпливатися. На етапі начинки можна додати ~80 г сухофруктів (наприклад, курагу), попередньо замочивши — маса стане пластичнішою.', 'https://www.instagram.com/reel/DQWWkeODByX/', 'family', 'published', '2026-02-08T14:00:00.000Z', '2026-02-08T14:00:00.000Z'),
('dish-004', (select id from public.families where slug='bulkina-family'), 'Човники з червоною рибою та овочами', 'chovnyky-z-chervonoiu-ryboiu', 'Запечена червона риба з овочами в пергаментних човниках під медово-соєвим соусом з гірчицею. Швидка, збалансована і дуже смачна вечеря для всієї сім''ї.', 5, 550, 'UAH', 10, 25, 35, 250, 2, 'easy', ARRAY['риба','червона риба','у духовці','овочі','соус']::text[], ARRAY['dinner','healthy','quick']::text[], 2, 3, 1, 0, 0, 5, 'Овочі можна брати будь-які на свій смак — спаржа, броколі Bimi теж чудово підходять. Якщо використовуєте філе, надріжте його для кращого пропікання.', 'https://www.instagram.com/reel/DFu_8MAty1V/', 'family', 'published', '2026-02-08T13:00:00.000Z', '2026-02-08T13:00:00.000Z'),
('dish-003', (select id from public.families where slug='bulkina-family'), 'Млинці-брізолі з курячим фаршем', 'mlyntsi-brizoli-z-kuriachym-farshem', 'Яєчні млинці з курячим фаршем, сиром та маринованими огірками або помідорами, запечені у духовці. Ідеальний варіант для обіду чи вечері.', 5, 280, 'UAH', 20, 30, 50, 210, 6, 'easy', ARRAY['брізолі','курка','фарш','у духовці','білкове']::text[], ARRAY['lunch','dinner','everyday','healthy']::text[], 0, 3, 1, 0, 1, 4, 'Начинки можуть бути різними — перець, гриби, шпинат. Робіть млинці якомога тоншими. Можна комбінувати два варіанти начинки: частину з огірками, частину з помідорами.', 'https://www.instagram.com/reel/DGqz03ptyUK/', 'family', 'published', '2026-02-08T12:00:00.000Z', '2026-02-08T12:00:00.000Z'),
('dish-002', (select id from public.families where slug='bulkina-family'), 'Млинці на молоці', 'mlyntsi-na-molotsi', 'Перевірені пропорції для ідеальних тоненьких млинців — тісто міцне, але м''якеньке. Більше молока — тонші, менше — суттєвіші. Для солоної начинки — 1 ст.л. цукру.', 5, 120, 'UAH', 10, 30, 40, 190, 15, 'easy', ARRAY['млинці','сніданок','на молоці','класика','тісто']::text[], ARRAY['breakfast','quick','everyday','snack']::text[], 2, 1, 0, 0, 0, 1, 'Додаємо половину молока і ВСЕ борошно на етапі густого тіста — так легше уникнути грудочок. Тісто можна зберігати як заготовку, але тоді краще замінити масло на олію або дати тісту відійти від холодильника перед приготуванням.', 'https://www.instagram.com/p/DTlJVJPiNmc/', 'family', 'published', '2026-02-08T11:00:00.000Z', '2026-02-08T11:00:00.000Z'),
('dish-001', (select id from public.families where slug='bulkina-family'), 'Ліниві хачапурі', 'lynyvi-khachapuri-bez-dukhovky', 'Швидкі ліниві хачапурі на сковороді — м''яке тісто на сметані з тягучою начинкою з моцарели та сулугуні. Ідеальний сніданок за 30 хвилин.', 5, 350, 'UAH', 15, 20, 35, 320, 4, 'easy', ARRAY['хачапурі','сніданок','на сковороді','сир','без духовки']::text[], ARRAY['breakfast','quick','everyday']::text[], 1, 3, 1, 0, 0, 4, 'Борошна може піти трохи більше або менше — орієнтуйтеся на консистенцію тіста. Смажити обов''язково під кришкою, щоб сир всередині добре розплавився.', 'https://www.instagram.com/reel/DT5VVNfCJsn/', 'family', 'published', '2026-02-08T10:00:00.000Z', '2026-02-28T11:06:47.933Z')
