insert into public.cooking_steps (dish_id, step_order, description, duration, image_url) values
('dish-034', 1, 'Обсмажити два рибних філе на сковороді з невеликою кількістю олії до готовності. Трохи остудити та розібрати виделкою на невеликі шматочки.', 10, null),
('dish-034', 2, 'Сир натерти на тертці. Змішати обсмажене філе з тертим сиром і соусом тартар. Сир і тартар додавайте на око, залежно від кількості риби — так, щоб начинка вийшла соковитою, а не сухою.', 5, null),
('dish-034', 3, 'Лаваш нарізати трикутниками або смужками. На кожен шматок викласти начинку та завернути з одного боку на інший, формуючи трикутник.', 10, null),
('dish-034', 4, 'Яйця (білок і жовток) злегка збити. Обмакнути кожен трикутник у яйце й обсмажити на розігрітій сковороді з олією до золотистої скоринки з обох боків.', 10, null),
('dish-033', 1, 'Куряче філе дуже дрібно нарубати ножем або коротко перебити блендером, щоб залишилась приємна текстура, а не повністю гладкий фарш.', 7, null),
('dish-033', 2, 'Цибулю дуже дрібно нарізати, часник подрібнити або пропустити через прес. Сир натерти.', 4, null),
('dish-033', 3, 'У великій мисці змішати філе, яйця, сир, йогурт або сметану, вівсянку, цибулю, часник, сіль, перець, паприку та італійські трави.', 3, null),
('dish-033', 4, 'Дати масі постояти 5–10 хвилин, щоб вівсянка трохи набухла і суміш стала стабільнішою.', 8, null),
('dish-033', 5, 'Розігріти сковороду на середньому вогні та додати трохи олії. Викладати масу ложкою, формуючи невеликі оладки або котлети.', 2, null),
('dish-033', 6, 'Смажити першу сторону приблизно 4 хвилини до золотистої скоринки.', 4, null),
('dish-033', 7, 'Перевернути, накрити кришкою і готувати ще 4–5 хвилин, поки котлети повністю не дійдуть всередині.', 5, null),
('dish-033', 8, 'Якщо маса занадто рідка, додати ще 1 ложку вівсянки. Якщо занадто щільна, додати ще 1 ложку йогурту або сметани.', 1, null),
('dish-032', 1, 'Філе нарізати подовгуватими смужками. Посолити, поперчити і додати борошно, добре перемішати, щоб кожна смужка була в легкому борошняному покритті.', 5, null),
('dish-032', 2, 'Розігріти сковороду з олією. Обсмажувати смужки курки в 2–3 заходи по кілька хвилин з кожної сторони до золотистої скоринки. Викласти на тарілку.', 8, null),
('dish-032', 3, 'У ту саму сковороду влити соєвий соус, теріякі, соус солодкий чилі, винний оцет та мед. Дати суміші закипіти та трохи проваритися, перемішати.', 2, null),
('dish-032', 4, 'Повернути курку в сковороду, перемішуючи 1–2 рази, протушкувати в соусі 5–7 хвилин до готовності та рівномірного покриття соусом.', 6, null),
('dish-032', 5, 'Посипати кунжутом і дрібно нарізаною зеленою цибулею. Подавати гарячою з гарніром або як самостійну страву.', 1, null),
('dish-031', 1, 'Шоколад разом із вершковим маслом розтопити на водяній бані або короткими імпульсами в мікрохвильовці. Перемішати до гладкої блискучої маси, дати трохи охолонути.', 5, null),
('dish-031', 2, 'Яйця збити з цукром до легкої світлої маси (~2–3 хвилини). Нам не потрібна дуже пишна піна.', 3, null),
('dish-031', 3, 'Влити теплу (не гарячу) шоколадну масу до яєчної суміші і обережно перемішати лопаткою.', 2, null),
('dish-031', 4, 'Додати просіяне борошно та какао. Перемішати до однорідності, але не перемішувати занадто довго.', 2, null),
('dish-031', 5, 'Перелити тісто у форму 18×18 см, вистелену пергаментом, і розрівняти.', 2, null),
('dish-031', 6, 'Випікати в розігрітій до 170°C духовці приблизно 23–25 хвилин — середина повинна залишатися трохи вологою.', 24, null),
('dish-031', 7, 'Дати повністю охолонути у формі, потім нарізати на квадрати. Подавати охолодженими або з морозивом.', 60, null),
('dish-030', 1, 'Для тіста з''єднати яйця, цукор, соду (погашену оцтом), какао та борошно. Добре перемішати до однорідності.', 10, null),
('dish-030', 2, 'Викласти тісто у форму та випікати при 180°C приблизно 15 хвилин.', 15, null),
('dish-030', 3, 'Для крему розтопити вершкове масло, додати какао й цукор, перемішати до однорідності.', 5, null),
('dish-030', 4, 'Дати масі охолонути, після чого додати сметану та перемішати до кремової консистенції.', 10, null),
('dish-030', 5, 'Готовий корж нарізати кубиками. Кожен кубик занурити в крем і викласти гіркою у формі «черепашки».', null, null),
('dish-030', 6, 'Поставити торт у холодильник до повного охолодження й стабілізації крему.', 120, null),
('dish-029', 1, 'Готуємо тісто. Масло заздалегідь дістаємо з холодильника — воно має бути м''яким. Змішуємо цукор, сіль, яйце, м''яке вершкове масло та розпушувач.', 5, null),
('dish-029', 2, 'Вводимо борошно частинами, замішуємо тісто. Загортаємо у плівку та прибираємо в холодильник на годину.', 65, null),
('dish-029', 3, 'Готуємо начинку. Змішуємо варене згущене молоко, яйця та сметану до однорідності.', 5, null),
('dish-029', 4, 'Дістаємо тісто з холодильника, розкачуємо та викладаємо у форму для випікання, формуючи бортики. Виливаємо начинку, зверху розкладаємо горішки.', 10, null),
('dish-029', 5, 'Випікаємо у попередньо розігрітій до 170°C духовці орієнтовно 35 хвилин до золотистого кольору.', 35, null),
('dish-029', 6, 'Дати пирогу охолонути при кімнатній температурі, а потім поставити в холодильник ще на годину перед подачею.', 60, null),
('dish-028', 1, 'Фарш добре відбити, приправити сіллю та перцем. Сформувати маленькі фрикадельки.', 10, null),
('dish-028', 2, 'Обсмажити фрикадельки на максимальному вогні до рум''яної скоринки з усіх боків.', 5, null),
('dish-028', 3, 'Додати шматочок вершкового масла та подрібнений часник, перемішати.', 2, null),
('dish-028', 4, 'Додати томатну пасту, травки та приправки. Добре перемішати.', 2, null),
('dish-028', 5, 'Всипати макарони, влити воду. Перемішати та готувати під кришкою до готовності макаронів.', 15, null),
('dish-028', 6, 'Перемішати, за потреби досолити. Подавати гарячим.', null, null),
('dish-027', 1, 'До борошна додати розпушувач і м''яке вершкове масло, перетерти руками в крихту.', 5, null),
('dish-027', 2, 'В окремій мисці з''єднати яйце, цукор, ванільний цукор і сметану. Додати до борошняної крихти та замісити м''яке тісто. Загорнути в пакет і відправити в холодильник на 1 годину.', 65, null),
('dish-027', 3, 'Для начинки з''єднати сир, цукор, борошно, сметану, білок і ванільний цукор. Перемішати до однорідності.', 5, null),
('dish-027', 4, 'Тісто поділити на 12-13 частин. Кожну розкачати в коло, на одну половину викласти чайну ложку сирної начинки і накрити другою половиною тіста.', 15, null),
('dish-027', 5, 'Змастити сочники жовтком і випікати в розігрітій до 180°C духовці протягом 30 хвилин.', 30, null),
('dish-027', 6, 'За бажанням остиглі сочники присипати цукровою пудрою.', null, null),
('dish-026', 1, 'Листково-дріжджове тісто розкачати та нарізати на трикутники.', 5, null),
('dish-026', 2, 'На широкий край кожного трикутника покласти шинку та сир.', 5, null),
('dish-026', 3, 'Скрутити круасани від широкого краю до вузького, надаючи їм характерну форму.', 5, null),
('dish-026', 4, 'Змастити круасани збитим жовтком та посипати кунжутом.', 2, null),
('dish-026', 5, 'Випікати в розігрітій до 180°C духовці протягом 20-30 хвилин до золотистого кольору.', 25, null),
('dish-025', 1, 'Приготувати опару: у теплому молоці розчинити дріжджі, додати трішки цукру та борошна. Перемішати, накрити та залишити в теплому місці на 10-15 хвилин.', 15, null),
('dish-025', 2, 'Просіяти борошно, додати цукор та сіль, перемішати. Вбити яйця, влити опару та розтоплене вершкове масло. Замісити тісто спочатку лопаткою, потім руками, поки не перестане липнути.', 15, null),
('dish-025', 3, 'Сформувати кульку, покласти в змащену олією миску, накрити харчовою плівкою та залишити в теплому місці на 1-2 години до подвоєння об''єму.', 120, null),
('dish-025', 4, 'Тісто обім''яти та розкачати у прямокутник товщиною 0.5 см. Змастити м''яким вершковим маслом та рівномірно посипати сумішшю цукру з корицею, залишивши один край без посипки.', 10, null),
('dish-025', 5, 'Скрутити тісто в тугий рулет та нарізати на 8-10 рівних частин. Викласти у форму для випікання.', 5, null),
('dish-025', 6, 'Випікати в розігрітій до 180°C духовці протягом 30-35 хвилин до золотистого кольору.', 35, null),
('dish-025', 7, 'Для крему змішати крем-сир з цукровою пудрою до однорідності. Гарячі булочки відразу змастити кремом та дати постояти 10 хвилин.', 12, null),
('dish-024', 1, 'Вівсяні пластівці перемолоти в блендері до стану борошна.', 2, null),
('dish-024', 2, 'До кисломолочного сиру додати яйця та переблендерити до однорідності.', 2, null),
('dish-024', 3, 'Всипати вівсяне борошно, змішане з розпушувачем та сіллю, і замісити однорідну масу.', 3, null),
('dish-024', 4, 'Розділити тісто на дві частини, викласти на деко, застелене просиліконеним пергаментом. Сформувати дві булки та посипати насінням.', 3, null),
('dish-024', 5, 'Випікати в добре розігрітій духовці при 180°C протягом 45-55 хвилин (орієнтуватися на свою духовку).', 50, null),
('dish-023', 1, 'До масла кімнатної температури додати цукор і ретельно перемішати.', 2, null),
('dish-023', 2, 'Додати яйця та молоко, перемішати до однорідності.', 2, null),
('dish-023', 3, 'Просіяти борошно з розпушувачем, додати до тіста і ретельно перемішати.', 3, null),
('dish-023', 4, 'Додати ягоди (можна будь-які — чорниці, малину тощо). Акуратно перемішати, щоб не пошкодити ягоди.', 2, null),
('dish-023', 5, 'Викласти тісто у форми для кексів і випікати при 200°C протягом 20 хвилин до зарум''янення.', 20, null),
('dish-022', 1, 'Печиво подрібнити в крихту, додати розтоплене вершкове масло та какао порошок. Все ретельно перемішати.', 5, null),
('dish-022', 2, 'У роз''ємній формі, застеленій пергаментом, сформувати основу та бортики за допомогою склянки. Відправити на 30 хв. до холодильника або морозильної камери.', 30, null),
('dish-022', 3, 'Для чізкейку крем сир поєднати з яйцями, цукром, ванільним цукром, вершками. Все перемішати вінчиком до однорідності, вкінці додати лимонний сік.', 10, null),
('dish-022', 4, 'Випікати чізкейк у розігрітій до 200°C духовці 10 хв., після чого зменшити температуру до 110°C і випікати ще 45 хв.', 55, null),
('dish-022', 5, 'Дати чізкейку повністю охолонути. Структура гарячого чізкейка трішки грає всередині, але після охолодження стає стабільною.', null, null),
('dish-022', 6, 'Для карамелі у посудині з товстим дном на мінімальному вогні розтопити цукор, додати вершкове масло, гарячі вершки та сіль. Проварити 4-5 хв. — карамель має трішки загуснути та ліниво стікати з лопатки.', 10, null),
('dish-022', 7, 'До теплої (не гарячої) карамелі додати підсмажений арахіс, покрити чізкейк зверху та відправити на 6-8 год. до холодильника.', 420, null),
('dish-020', 1, 'У теплому молоці розчинити дріжджі та 1 ст.л. цукру. Залишити на 10 хвилин до появи піни.', 10, null),
('dish-020', 2, 'До борошна додати сіль, цукор, ванільний цукор, жовтки та розм''якшене масло. Влити дріжджову суміш і замісити м''яке еластичне тісто. Накрити та залишити підходити на 60 хвилин.', 65, null),
('dish-020', 3, 'Тісто обім''яти та поділити на 6 частин. Кожну частину розкачати у довгу смужку шириною ~2 см.', null, null),
('dish-020', 4, 'Намотати смужку тіста спіраллю на дерев''яний або металевий валик (або на конус з фольги), злегка розтягуючи.', 10, null),
('dish-020', 5, 'Випікати у розігрітій духовці при 200°C протягом 15–20 хвилин, обертаючи для рівномірного підрум''янювання.', 20, null),
('dish-020', 6, 'Гарячий трдельник змастити розтопленим маслом та обваляти у суміші цукру, кориці та горіхів або кокосової стружки.', null, null),
('dish-019', 1, 'Листкове тісто розморозити та розкачати у тонкий пласт. Змастити томатною пастою.', 5, null),
('dish-019', 2, 'Шинку та сир натерти на терці. Рівномірно розподілити начинку по тісту.', 3, null),
('dish-019', 3, 'Згорнути тісто у щільний рулет. Нарізати на кружальця товщиною ~2 см.', 3, null),
('dish-019', 4, 'Викласти кружальця на деко з пергаментом, змастити збитим яйцем.', 2, null),
('dish-019', 5, 'Запікати при 180°C протягом 18–20 хвилин до золотистого кольору.', 20, null),
('dish-018', 1, 'Рис гарно промити під проточною водою та залишити замочуватись на 30 хвилин.', 30, null),
('dish-018', 2, 'На олії обсмажити цибулю до легкої золотистості, додати нарізане м''ясо, обсмажити. Потім додати нарізану соломкою моркву.', 15, null),
('dish-018', 3, 'Додати приправи (паприку, куркуму, сіль, перець, орегано), залити водою. Всередину покласти цілу головку часнику. Тушкувати під кришкою 40–60 хвилин.', 50, null),
('dish-018', 4, 'Зверху рівномірно розподілити рис, залити водою на палець вище рису. Готувати під кришкою на великому вогні, поки вода не зрівняється з рисом.', 10, null),
('dish-018', 5, 'Зменшити вогонь до мінімуму та готувати до повної готовності рису.', 20, null),
('dish-018', 6, 'Вимкнути вогонь і дати плову настоятись 30 хвилин під кришкою. Перед подачею акуратно перемішати.', 30, null),
('dish-017', 1, 'Із усіх інгредієнтів замісити м''яке тісто. Накрити та залишити підходити на 1 годину.', 65, null),
('dish-017', 2, 'Розділити тісто на 6 рівних частин (з цієї кількості вийде 2 пироги). Кожну частину розкачати в круглий пласт.', 10, null),
('dish-017', 3, 'Перший пласт викласти на пергамент, розподілити начинку. Накрити другим пластом, знову начинка, зверху третій. Посередині покласти круглу тарілочку.', null, null),
('dish-017', 4, 'Розрізати на 12 рівних частин (від тарілочки до краю). Кожні дві частини прокрутити та добре защіпнути краї.', 5, null),
('dish-017', 5, 'Накрити та залишити на 20–30 хвилин. Змастити збитим яйцем.', 25, null),
('dish-017', 6, 'Випікати у розігрітій духовці при 180°C протягом 20–25 хвилин до золотистого кольору.', 25, null),
('dish-016', 1, 'Свинину нарізати шматочками, обсмажити на сковороді до золотистої скоринки.', 10, null),
('dish-016', 2, 'Додати нарізану цибулю та моркву, обсмажити 5 хвилин.', 5, null),
('dish-016', 3, 'Додати нарізані печериці та томатну пасту, перемішати. Присипати борошном.', 5, null),
('dish-016', 4, 'Додати нарізану картоплю, залити водою. Посолити, поперчити, додати спеції. Тушкувати під кришкою до готовності картоплі.', 25, null),
('dish-015', 1, 'Збити яйця з цукром до пишної маси. Додати розтоплене (не гаряче) масло, перемішати.', 5, null),
('dish-015', 2, 'Додати сметану та перемішати. Просіяти борошно з розпушувачем і содою, злегка вмішати.', 5, null),
('dish-015', 3, 'Розділити тісто на 2 частини. В одну додати какао та перемішати.', 2, null),
('dish-015', 4, 'Викладати тісто по черзі у форму — ложку світлого, потім ложку темного, поки тісто не закінчиться. За бажанням зробити візерунок шпажкою.', 5, null),
('dish-015', 5, 'Випікати у розігрітій духовці при 180°C протягом 45–55 хвилин. Перевірити готовність дерев''яною шпажкою.', 50, null),
('dish-014', 1, 'Борошно та сіль перемішати, зробити заглиблення. Влити воду та олію, замісити еластичне тісто. Накрити плівкою, дати відпочити 20 хвилин.', 25, null),
('dish-014', 2, 'Цукор змішати з крохмалем — це буде посипка для начинки.', 2, null),
('dish-014', 3, 'Тісто розділити на 2 частини, кожну розкачати в довгий джгутик і нарізати на шматочки. Кожен шматочок тонко розкачати в овал.', 10, null),
('dish-014', 4, 'На центр насипати трохи цукру з крохмалем, викласти 2–3 вишні. Защіпнути краї.', 10, null),
('dish-014', 5, 'Вареники опустити в киплячу воду, акуратно перемішати. Варити 5 хвилин після того, як спливуть. Вода не має активно кипіти.', 8, null),
('dish-013', 1, 'Яблука помити, очистити від серцевини та нарізати тонкими скибочками.', 5, null),
('dish-013', 2, 'Масло розтопити, додати цукор та яйця. Збити до однорідності.', 5, null),
('dish-013', 3, 'Додати борошно, крохмаль та розпушувач. Перемішати до гладкого тіста.', 3, null),
('dish-013', 4, 'Викласти тісто у змащену форму, зверху розкласти шматочки яблук.', 3, null),
('dish-013', 5, 'Випікати при 190°C протягом 30 хвилин до золотистого кольору. Перевірити готовність шпажкою.', 30, null),
('dish-012', 1, 'Картоплю почистити та нарізати кружальцями або часточками. Викласти у форму для випікання.', 10, null),
('dish-012', 2, 'Фарш посолити, додати спеції та рівномірно розподілити поверх картоплі.', 5, null),
('dish-012', 3, 'Заливка: змішати томатну пасту, сметану та вершки. Залити зверху.', 3, null),
('dish-012', 4, 'Запікати при 180°C до готовності картоплі — приблизно 40–45 хвилин.', 45, null),
('dish-011', 1, 'Яйця збити з цукром та сіллю. Додати молоко, борошно та розтоплене масло. Перемішати до однорідності.', 5, null),
('dish-011', 2, 'Деко застелити пергаментом, вилити тісто рівним шаром.', 2, null),
('dish-011', 3, 'Випікати у розігрітій духовці при 200°C протягом 15–20 хвилин до золотистого кольору.', 20, null),
('dish-011', 4, 'Гарячий млинець посипати кокосовою стружкою та одразу скрутити в рулет. Нарізати порціями.', null, null),
('dish-010', 1, 'Опара: в теплому молоці розчинити дріжджі та цукор, додати яйце. Перемішати та залишити на 15 хвилин.', 15, null),
('dish-010', 2, 'До опари додати борошно, сіль і розм''якшене масло. Замісити м''яке тісто. Накрити та залишити підходити на 40 хвилин.', 45, null),
('dish-010', 3, 'Тісто обім''яти, поділити на порції. Кожну розкачати, покласти макову начинку, сформувати булочки.', null, null),
('dish-010', 4, 'Викласти на деко з пергаментом, дати підійти 15 хвилин. Випікати при 180°C 20–25 хвилин.', 25, null),
('dish-009', 1, 'Тісто: до окропу додати олію та сіль. Поступово всипати борошно, замісити еластичне тісто. Загорнути в плівку й прибрати в холодильник на 1 годину.', 70, null),
('dish-009', 2, 'Начинка: фарш змішати з дрібно нарізаною цибулею, кінзою, сіллю, перцем. Додати крижану воду — це зробить начинку соковитою.', 10, null),
('dish-009', 3, 'Тісто поділити на шматочки, кожен розкачати в тонкий кружечок. На одну половину викласти начинку, закрити другою, ретельно защіпнути краї виделкою.', null, null),
('dish-009', 4, 'Смажити у великій кількості розігрітої олії з обох боків до золотистої хрусткої скоринки.', 30, null),
('dish-008', 1, 'Борошно змішати з сіллю. Поступово додавати воду, розмішуючи до однорідної рідкої консистенції.', 3, null),
('dish-008', 2, 'За бажанням додати яйце та перемішати.', 1, null),
('dish-008', 3, 'Розігріти сковороду, злегка змастити олією.', 1, null),
('dish-008', 4, 'Наливати тісто тонким шаром на гарячу сковороду, обсмажувати з двох боків до золотистого кольору.', 25, null),
('dish-007', 1, 'Печиво порубати на шматочки різного розміру — частину крупніше, частину дрібніше.', 5, null),
('dish-007', 2, 'Горіхи підсмажити на сухій сковороді та порубати.', 5, null),
('dish-007', 3, 'Масло розтопити, додати цукор, какао та молоко. Перемішати до однорідності.', 5, null),
('dish-007', 4, 'Додати печиво та горіхи до шоколадної маси. Ретельно перемішати.', 3, null),
('dish-007', 5, 'Викласти масу на харчову плівку, сформувати щільну ковбаску. Загорнути та скрутити краї.', 5, null),
('dish-007', 6, 'Прибрати в холодильник мінімум на 3–4 години. Нарізати на кружальця перед подачею.', 180, null),
('dish-006', 1, 'Макарони відварити до напівготовності, злити воду.', 8, null),
('dish-006', 2, 'Цибулю подрібнити, обсмажити з фаршем до готовності. Додати соус, сіль та спеції.', 10, null),
('dish-006', 3, 'У форму для випікання викласти макарони, зверху фарш. Залити вершками, посипати тертим сиром.', null, null),
('dish-006', 4, 'Запікати у розігрітій духовці при 180°C протягом 20 хвилин до золотистої скоринки.', 20, null),
('dish-005', 1, 'У молоко додати вершкове масло і злегка підігріти. Яйця дістати заздалегідь з холодильника.', 5, null),
('dish-005', 2, 'У 300 г борошна додати дріжджі, сіль і ванілін. До молочно-масляної суміші додати яйця, цукор і перемішати. Поступово всипати борошно, замісити м''яке тісто. Накрити і залишити на 60 хвилин.', 70, null),
('dish-005', 3, 'Начинка: мак залити водою, довести до кипіння і варити 10 хвилин. Злити воду, додати молоко і варити ще 10–15 хвилин. Злити рідину, пробити блендером. Додати цукор.', 30, null),
('dish-005', 4, 'Тісто обім''яти, розкачати у пласт ~40×50 см. Рівномірно розподілити макову начинку, відступивши від одного краю 4 см. Скрутити у щільний рулет, защіпнути шов.', null, null),
('dish-005', 5, 'Рулет розрізати вздовж посередині, відступивши від краю ~4 см. Акуратно переплести обидві частини між собою у косичку.', null, null),
('dish-005', 6, 'Форму (30×13 см) застелити пергаментом, перекласти кранч. Накрити рушником і залишити підходити на 25 хвилин.', 25, null),
('dish-005', 7, 'Випікати у розігрітій духовці при 170°C протягом 30–35 хвилин. За бажанням полити сиропом (вода + цукор, прокип''ятити).', 35, null),
('dish-004', 1, 'Філе рибки розділити на рівні шматочки. Кожен шматочок надрізати, але не до кінця, і вивернути — так рибка приготується швидше і буде соковитіша.', 5, null),
('dish-004', 2, 'З пергаменту зробити човники. Викласти в кожен овочі: нарізані четвертинками гриби, бейбі морквину, черрі. Трохи підсолити овочі. Зверху покласти шматочок риби.', null, null),
('dish-004', 3, 'Для соусу змішати оливкову олію, соєвий соус, лимонний сік, мед, гірчицю та спеції.', 2, null),
('dish-004', 4, 'Щіточкою змастити рибку соусом і трохи добавити до овочів.', 2, null),
('dish-004', 5, 'Запікати при 180°C протягом 20–25 хвилин.', 25, null),
('dish-003', 1, 'Збити яйця з молоком, сіллю і перцем. Посмажити тонкі яєчні млинці на сковороді з обох боків на малому вогні. Має вийти 6 млинців.', 10, null),
('dish-003', 2, 'Подрібнити цибулю і часник, додати до фаршу. Посолити, поперчити й все добре вимішати.', 5, null),
('dish-003', 3, 'Змастити кожен млинець тонким шаром фаршу. Викласти нарізаний огірок чи помідор, присипати тертим сиром.', null, null),
('dish-003', 4, 'Скрутити млинці в рулети й щільно укласти у форму для випічки.', 3, null),
('dish-003', 5, 'Запікати при 180°C протягом 30 хвилин. Подавати гарячими.', 30, null),
('dish-002', 1, 'Яйця збити з цукром і сіллю до однорідності.', 2, null),
('dish-002', 2, 'Додати половину молока та ВСЕ борошно. Замішати густеньке тісто без грудочок.', 3, null),
('dish-002', 3, 'Влити решту молока, перемішати до рідкої консистенції. Додати розтоплене вершкове масло.', 2, null),
('dish-002', 4, 'Добре розігріти сковороду, злегка змастити олією або маслом.', 2, null),
('dish-002', 5, 'Набирати тісто половником, наливати на сковороду тонким шаром, швидко обертаючи, щоб тісто розтеклось рівномірно.', null, null),
('dish-002', 6, 'Смажити на середньому вогні до золотистих бочків — приблизно 1–1.5 хвилини з кожного боку.', 25, null),
('dish-002', 7, 'Готові млинці складати стопкою, за бажанням змащуючи маслом. Подавати з улюбленою начинкою.', null, null),
('dish-001', 1, 'До сметани додати сіль, цукор і соду. Ретельно перемішати — сметана вступає в реакцію та стає більш пухкою.', 3, null),
('dish-001', 2, 'Поступово ввести борошно, підсипаючи частинами. Замісити м''яке, еластичне тісто — воно не повинно липнути до рук.', 5, null),
('dish-001', 3, 'Готове тісто сформувати в кульку та поділити на 4 рівні частини.', null, null),
('dish-001', 4, 'Моцарелу й сулугуні натерти на крупну терку, змішати. Поділити сирну масу на 4 частини та сформувати з кожної кульку.', 5, null),
('dish-001', 5, 'Кожен шматочок тіста розкачати, викласти всередину сирну кульку та ретельно защіпнути краї, щоб не залишалося отворів. Сформувати кульку й обережно розкачати качалкою в плаский хачапурі.', null, null),
('dish-001', 6, 'Смажити на добре розігрітій сухій сковороді на вогні нижче середнього. Готувати під кришкою, перевертаючи 2–3 рази до рум''яної скоринки з обох боків.', 15, null),
('dish-001', 7, 'Готові хачапурі одразу змастити вершковим маслом.', null, null);
